# AUTO-GENERATED by phi_gencheck.py -- UML phi amplitudes as user_amplitudes(Q2, xB, t)
# for vecmeson_generator (--tuned_to_data, or AMP_FILE=this file). Nodes: nodes.npz next to this file.
# interp = "bin":    the amplitudes of the (Q^2, x_B, |t|) bin containing the point (nearest bin outside)
# interp = "linear": per Q^2 window, per x_B window: linear in |t| through the node positions; then
#                    linear in x_B between the x_B windows; then linear in Q^2 between the Q^2 windows.
#                    The SCALE |A|^2 is interpolated in log (and extrapolated linearly in log within
#                    the covered box), the DIRECTION A/|A| linearly (clamped at the outer nodes).
import os
import numpy as np
_Z = np.load(os.path.join(os.path.dirname(os.path.abspath(__file__)), "nodes.npz"))
_A, _POS, _LO, _HI = _Z["A"], _Z["pos"], _Z["lo"], _Z["hi"]
INTERP = "linear"
# SMOOTH MAGNITUDE (2026-11-04): if the node file carries "beta", log(sum A^2) is a polynomial in (log Q2, log xB, |t|)
# fitted to all nodes (phi_gencheck.write_amp_files, mag_model = poly2); only the direction of the amplitude vector is
# still interpolated between nodes. Without "beta" the magnitude is the piecewise log-linear interpolation (old behaviour).
_BETA = _Z["beta"] if "beta" in _Z.files else None


def _poly_feats(Q2, xB, t, n):
    lq, lx = np.log(np.maximum(Q2, 1e-6)), np.log(np.maximum(xB, 1e-6))
    cols = [np.ones_like(lq), lq, lx, t, t * t] + ([lq * lq, lx * lx] if n >= 7 else []) + ([lq * lx, lq * t, lx * t] if n == 10 else [])
    return np.stack(cols, -1)


def _lin(x, xs, ys, extrap):
    """vectorised piecewise-linear interpolation of rows ys (n,16) at x; linear extrapolation
    if extrap else clamped."""
    o = np.argsort(xs); xs, ys = np.asarray(xs)[o], np.asarray(ys)[o]
    if len(xs) == 1:
        return np.broadcast_to(ys[0], x.shape + ys.shape[1:]).copy()
    i = np.clip(np.searchsorted(xs, x) - 1, 0, len(xs) - 2)
    w = (x - xs[i]) / (xs[i + 1] - xs[i])
    if not extrap:
        w = np.clip(w, 0.0, 1.0)
    return ys[i] + w[..., None] * (ys[i + 1] - ys[i])


def _split(A):
    s = np.maximum(np.sum(A * A, -1), 1e-300)
    return np.log(s), A / np.sqrt(s)[..., None]


def _interp_rows(x, xs, A):
    ls, u = _split(A)
    L = _lin(x, xs, ls[:, None], True)[..., 0]
    U = _lin(x, xs, u, False); U /= np.linalg.norm(U, axis=-1, keepdims=True)
    return np.exp(L)[..., None], U


def _params(Q2, xB, t):
    Q2, xB, t = np.broadcast_arrays(np.asarray(Q2, float), np.asarray(xB, float), np.asarray(t, float))
    if INTERP == "bin":
        X = np.stack([Q2, xB, t], -1)[..., None, :]
        d = np.maximum(np.maximum(_LO - X, X - _HI), 0) / (_HI - _LO)      # 0 inside a bin
        return _A[np.argmin(np.sum(d * d, -1), -1)]
    # linear: group nodes by Q^2 window, then x_B window
    qkeys = sorted(set(map(tuple, np.round(np.c_[_LO[:, 0], _HI[:, 0]], 6))))
    per_q_S, per_q_U, qpos = [], [], []
    for qk in qkeys:
        mq = np.all(np.isclose(np.c_[_LO[:, 0], _HI[:, 0]], qk), 1)
        xkeys = sorted(set(map(tuple, np.round(np.c_[_LO[mq, 1], _HI[mq, 1]], 6))))
        S_x, U_x, xpos = [], [], []
        for xk in xkeys:
            mx = mq & np.all(np.isclose(np.c_[_LO[:, 1], _HI[:, 1]], xk), 1)
            S, U = _interp_rows(t, _POS[mx, 2], _A[mx])
            S_x.append(np.log(S[..., 0])); U_x.append(U); xpos.append(_POS[mx, 1].mean())
        S_x, U_x, xpos = np.stack(S_x, -1), np.stack(U_x, -2), np.array(xpos)
        o = np.argsort(xpos); S_x, U_x, xpos = S_x[..., o], U_x[..., o, :], xpos[o]
        if len(xpos) == 1:
            S1, U1 = S_x[..., 0], U_x[..., 0, :]
        else:
            i = np.clip(np.searchsorted(xpos, xB) - 1, 0, len(xpos) - 2)
            w = np.clip((xB - xpos[i]) / (xpos[i + 1] - xpos[i]), 0, 1)
            S1 = np.take_along_axis(S_x, i[..., None], -1)[..., 0] * (1 - w) + np.take_along_axis(S_x, (i + 1)[..., None], -1)[..., 0] * w
            Ua = np.take_along_axis(U_x, i[..., None, None], -2)[..., 0, :]
            Ub = np.take_along_axis(U_x, (i + 1)[..., None, None], -2)[..., 0, :]
            U1 = Ua * (1 - w)[..., None] + Ub * w[..., None]
        per_q_S.append(S1); per_q_U.append(U1); qpos.append(_POS[mq, 0].mean())
    S, U, qpos = np.stack(per_q_S, -1), np.stack(per_q_U, -2), np.array(qpos)
    o = np.argsort(qpos); S, U, qpos = S[..., o], U[..., o, :], qpos[o]
    if len(qpos) == 1:
        S1, U1 = S[..., 0], U[..., 0, :]
    else:
        i = np.clip(np.searchsorted(qpos, Q2) - 1, 0, len(qpos) - 2)
        w = np.clip((Q2 - qpos[i]) / (qpos[i + 1] - qpos[i]), 0, 1)
        S1 = np.take_along_axis(S, i[..., None], -1)[..., 0] * (1 - w) + np.take_along_axis(S, (i + 1)[..., None], -1)[..., 0] * w
        U1 = (np.take_along_axis(U, i[..., None, None], -2)[..., 0, :] * (1 - w)[..., None]
              + np.take_along_axis(U, (i + 1)[..., None, None], -2)[..., 0, :] * w[..., None])
    U1 = U1 / np.linalg.norm(U1, axis=-1, keepdims=True)
    if _BETA is not None:                      # nodes carry the RESIDUAL to the smooth model; add the model back
        S1 = S1 + _poly_feats(Q2, xB, t, len(_BETA)) @ _BETA
    return np.exp(0.5 * S1)[..., None] * U1


def user_amplitudes(Q2, xB, t):
    p = _params(Q2, xB, t)
    c = lambda re, im: p[..., re] + 1j * p[..., im]
    return (p[..., 0], c(1, 2), c(3, 4), c(5, 6), c(7, 8), p[..., 9], c(10, 11), c(12, 13), c(14, 15))


if _A.shape[1] == 22:        # S + P table: the 6 S-wave parameters (S00, S01 natural; V01 unnatural; re, im)
    def user_swave(Q2, xB, t):
        return _params(Q2, xB, t)[..., 16:22]

if _A.shape[1] == 32:        # nucleon-helicity-flip set (UML_FLIP=1): columns 16..31 = the second 16-vector, added incoherently
    def user_amplitudes_second(Q2, xB, t):
        p = _params(Q2, xB, t)[..., 16:32]
        c = lambda re, im: p[..., re] + 1j * p[..., im]
        return (p[..., 0], c(1, 2), c(3, 4), c(5, 6), c(7, 8), p[..., 9], c(10, 11), c(12, 13), c(14, 15))
